// validateRestored 校验从文件恢复的待确认交接关联是否一致...
func validateRestored(l *ledger) error {
    sampleIDs := make([]string, 0, len(l.Samples))
    for id := range l.Samples {
        sampleIDs = append(sampleIDs, id)
    }
    sort.Strings(sampleIDs)
    for _, id := range sampleIDs {
        rec := l.Samples[id]
        if rec == nil {
            return fmt.Errorf("%w: 样品编号 %q 占用了编号但没有对应记录，无法恢复", ErrInvalid, id)
        }
        if rec.PendingID == "" {
            continue
        }
        tr, ok := l.Transfers[rec.PendingID]
        if !ok {
            return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 不存在，无法恢复", ErrInvalid, id, rec.PendingID)
        }
        if tr == nil {
            return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 没有对应记录，无法恢复", ErrInvalid, id, rec.PendingID)
        }
        if tr.Confirmed {
            return fmt.Errorf("%w: 样品 %q 指向的交接 %q 已确认，无法恢复为待确认状态", ErrInvalid, id, rec.PendingID)
        }
        if tr.SampleID != id {
            return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 实际属于样品 %q，无法恢复", ErrInvalid, id, rec.PendingID, tr.SampleID)
        }
    }
    transferIDs := ...sorted
    for _, id := range transferIDs {
        rec := l.Transfers[id]
        if rec == nil {
            return fmt.Errorf("%w: 交接编号 %q 占用了编号但没有对应记录，无法恢复", ErrInvalid, id)
        }
        if rec.Confirmed {
            continue // 已确认交接属于保留的历史
        }
        sample, ok := l.Samples[rec.SampleID]
        if !ok || sample == nil {
            return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 不存在，无法恢复", ErrInvalid, id, rec.SampleID)
        }
        if sample.PendingID != id {
            return fmt.Errorf("%w: 待确认交接 %q 的样品 %q 未记录该交接编号，无法恢复", ErrInvalid, id, rec.SampleID)
        }
    }
    return nil
}
